python3 -c "
import json
with open('/app/resources/treasury_bulletin_2000_09.json') as f:
    d = json.load(f)

# Search for any key containing 'sustain' or 'indicator'
def search_keys(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'sustain' in k.lower() or 'indicator' in k.lower() or 'debt' in k.lower():
                print(f'{path}.{k}')
            search_keys(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):
            search_keys(item, f'{path}[{i}]')

search_keys(d)
"
